import java.util.*;

public class hi {
    private static long solve(long n, long m) {
        if (n >= 4L && m >= 4L) {
            long product = n * m;
            return (product & 1L) == 0L ? product : product - 1L;
        }

        long min = Math.min(n, m);
        long max = Math.max(n, m);

        if (min == 1L) {
            long rem = max % 6L;
            long extra = 0L;
            switch ((int) rem) {
                case 4: extra = 2L; break;
                case 5: extra = 4L; break;
                default: break;
            }
            return max - rem + extra;
        }

        if (min == 2L) {
            switch (Long.toString(max)) {
                case "2": return 0L;
                case "3": return 4L;
                case "7": return 12L;
                default: return 2L * max;
            }
        }

        if (min == 3L) {
            if (max < 3L) return 0L;
            return 3L * max - (max & 1L);
        }

        return 0L;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long m = sc.nextLong();
        System.out.println(solve(n, m));
    }
}
